oxy_webhelp_navlinks = {"manage_db2_objects-d39536e34570":{"topics":[{"title":"Viewing Db2 instances","shortdesc":"<p class=\"shortdesc\">View a list of all         added         Db2 instances on <span class=\"ph\">RSC<\/span>, including their status and connectivity         details.<\/p>","href":"db2\/viewing_db2_instances.html","attributes":{"data-id":"viewing_db2_instances"},"menu":{"hasChildren":false},"tocID":"viewing_db2_instances-d39536e34584","topics":[]},{"title":"Editing a Db2 database instance","shortdesc":"<p class=\"shortdesc\">To modify a Db2 database instance protected by a Rubrik cluster, edit the Db2         database instance settings.<\/p>","href":"db2\/editing_db2_db_instance.html","attributes":{"data-id":"editing_db2_db_instance"},"menu":{"hasChildren":false},"tocID":"editing_db2_db_instance-d39536e34598","topics":[]},{"title":"Refreshing a Db2 database instance","shortdesc":"<p class=\"shortdesc\">To ensure that the information on a Rubrik cluster is up to date and accurate,         refresh the Db2 database instance. When you refresh a Db2 database instance, all databases         local to the selected instance are discovered and the relevant metadata is         updated.<\/p>","href":"db2\/refreshing_db2_db_instance.html","attributes":{"data-id":"refreshing_db2_db_instance"},"menu":{"hasChildren":false},"tocID":"refreshing_db2_db_instance-d39536e34609","topics":[]},{"title":"Deleting a Db2 database instance","shortdesc":"<p class=\"shortdesc\">To manage and organize the Rubrik cluster by removing databases that are not         contributing to a Db2 workload, delete the Db2 database instance.<\/p>","href":"db2\/deleting_db2_db_instance.html","attributes":{"data-id":"deleting_db2_db_instance"},"menu":{"hasChildren":false},"tocID":"deleting_db2_db_instance-d39536e34620","topics":[]},{"title":"Db2 database details","shortdesc":"<p class=\"shortdesc\">Information about the selected Db2 database, including the Overview, Events, and         Snapshots tabs, and the available actions.<\/p>","href":"db2\/db2_db_details.html","attributes":{"data-id":"db2_db_details"},"menu":{"hasChildren":false},"tocID":"db2_db_details-d39536e34631","next":"db2_db_details-d39536e34631"},{"title":"Viewing events for Db2","shortdesc":"<p class=\"shortdesc\">View events for Db2 workloads to monitor backups, log archival, configuration         updates, and recovery operations on Db2 databases.<\/p>","href":"db2\/viewing_events_db2.html","attributes":{"data-id":"viewing_events_db2"},"menu":{"hasChildren":false},"tocID":"viewing_events_db2-d39536e34664","next":"viewing_events_db2-d39536e34664"},{"title":"Post RBS upgrade management for Db2 on Windows","shortdesc":"<p class=\"shortdesc\">After the Rubrik Backup Service upgrade, Db2 may encounter errors due to outdated         processes. Restarting the database manager fixes the issue by updating necessary processes,         ensuring that Db2 archives logs without errors.<\/p>","href":"db2\/post_rbs_upgrade_mgmt_db2_win.html","attributes":{"data-id":"post_rbs_upgrade_mgmt_db2_win"},"menu":{"hasChildren":false},"tocID":"post_rbs_upgrade_mgmt_db2_win-d39536e34686","topics":[]}]}};